import { AnyRouter, ProcedureType, inferProcedureInput, inferProcedureOutput } from '@trpc/server';
import { IntersectionError } from '@trpc/server/src/error/formatter';
import { mergeMiddlewares } from './mergeMiddlewares';

type MergeRouters<TRouters extends AnyRouter[]> = {
  [K in keyof TRouters]: TRouters[K];
}[number];

export function mergeRouters<TRouters extends AnyRouter[]>(...routerList: [...TRouters]): MergeRouters<TRouters> {
  const mergedRouter: any = {};

  for (const router of routerList) {
    for (const [key, procedure] of Object.entries(router._def.procedures)) {
      if (mergedRouter[key]) {
        throw new IntersectionError(`Duplicate procedure name: ${key}`);
      }
      mergedRouter[key] = procedure;
    }
  }

  for (const router of routerList) {
    for (const [key, middleware] of Object.entries(router._def.middlewares)) {
      if (mergedRouter[key]) {
        mergedRouter[key] = mergeMiddlewares(mergedRouter[key], middleware);
      } else {
        mergedRouter[key] = middleware;
      }
    }
  }

  return mergedRouter as MergeRouters<TRouters>;
}

