type MergeRouters<TRouters extends AnyRouter[]> = UnionToIntersection<
  TRouters[number] extends infer TRouter
    ? {
        [TKey in keyof TRouter]: TRouter[TKey] extends infer TProcedure
          ? TProcedure extends Procedure<infer TType, infer TInput, infer TOutput>
            ? Procedure<
                TType,
                inferProcedureInput<TProcedure>,
                inferProcedureOutput<TProcedure>
              >
            : never
          : never;
      }
    : never
>;

export function mergeRouters<TRouters extends AnyRouter[]>(...routerList: [...TRouters]): MergeRouters<TRouters> {
  const mergedRouter: any = {};

  for (const router of routerList) {
    for (const key in router) {
      if (router.hasOwnProperty(key)) {
        const procedure = router[key];

        if (mergedRouter[key]) {
          throw new Error(`Duplicate procedure key: ${key}`);
        }

        mergedRouter[key] = procedure;
      }
    }
  }

  return mergedRouter;
}

