import { MonoTypeOperatorFunction, Observable, Subscriber, Subscription } from 'rxjs';

interface ShareConfig {
  // Define any configuration options here if needed
}

export function share<TValue, TError>(_opts?: ShareConfig): MonoTypeOperatorFunction<TValue, TError> {
  return (source: Observable<TValue>) => {
    let sharedSubscription: Subscription | null = null;
    let subscribers: Subscriber<TValue>[] = [];

    return new Observable<TValue>((subscriber) => {
      subscribers.push(subscriber);

      if (!sharedSubscription) {
        sharedSubscription = source.subscribe({
          next: (value) => {
            subscribers.forEach((sub) => sub.next(value));
          },
          error: (error) => {
            subscribers.forEach((sub) => sub.error(error));
            subscribers = [];
          },
          complete: () => {
            subscribers.forEach((sub) => sub.complete());
            subscribers = [];
          },
        });
      }

      return () => {
        const index = subscribers.indexOf(subscriber);
        if (index >= 0) {
          subscribers.splice(index, 1);
        }

        if (subscribers.length === 0 && sharedSubscription) {
          sharedSubscription.unsubscribe();
          sharedSubscription = null;
        }
      };
    });
  };
}

